CREATE OR REPLACE FUNCTION public.paymaster_assignment_candidates() RETURNS TABLE(user_id uuid,name text,email text,home_company text,home_org_id uuid,org_ids uuid[]) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform Super Admin required'; END IF; RETURN QUERY SELECT p.user_id,trim(coalesce(p.first_name,'')||' '||coalesce(p.last_name,'')),p.email,o.name,p.org_id,coalesce((SELECT array_agg(a.org_id) FROM public.company_admin_access a WHERE a.user_id=p.user_id),'{}'::uuid[]) FROM public.profiles p JOIN public.organizations o ON o.id=p.org_id WHERE p.deleted_at IS NULL AND p.status='Active' AND NOT public.has_role(p.user_id,'admin') AND NOT EXISTS(SELECT 1 FROM public.platform_administrators pa WHERE pa.user_id=p.user_id) ORDER BY 2; END $$; REVOKE ALL ON FUNCTION public.paymaster_assignment_candidates() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.paymaster_assignment_candidates() TO authenticated;